import type { CatalogImage } from "@/types/catalog";
import manifest from "@/lib/image-manifest.json";

export type CatalogImageId = keyof typeof manifest;

/**
 * Real client photography, generated by scripts/build-images.mjs from the
 * originals in photography-inbox/. Ids are checked at compile time against
 * lib/image-manifest.json, so a missing photo fails the build.
 */
export function catalogImage(id: CatalogImageId, alt: string): CatalogImage {
  const { src, width, height, blurDataURL } = manifest[id];
  return { src, alt, width, height, blurDataURL };
}
